user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning node records an explicit prospective plan that commits the agent to one or more future operations or checks.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "Agent-authored text that may state a plan."
      }
    ],
    "assertion_conditions": [
      "The text uses prospective language such as 'I will', 'next', or 'let me' to describe operations not yet reported as completed in that reasoning text.",
      "At least one concrete future action or verification step is identifiable from the text."
    ],
    "exclusion_conditions": [
      "A retrospective diagnosis, summary, or conclusion about already observed results is not a plan.",
      "A generic statement of intent without an identifiable future operation does not satisfy this predicate."
    ]
  },
  {
    "name": "EXECUTES_PLANNED_STEP",
    "definition": "The action carries out an operation that the plan reasoning node specifies as the next step, with the plan supplying the operative instruction for the action.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action that performs the planned operation."
      },
      {
        "name": "plan",
        "type": "reasoning",
        "description": "The prior reasoning node that states the operation to be performed."
      }
    ],
    "assertion_conditions": [
      "The plan node precedes the action and names the operation or its essential parameters in prospective terms.",
      "The action's tool and arguments correspond to that named operation, so the action implements the plan rather than merely sharing its topic or resource."
    ],
    "exclusion_conditions": [
      "A plan that only mentions the same resource or goal without specifying the performed operation does not satisfy this predicate.",
      "Temporal adjacency or a shared topic without an observable correspondence between the planned operation and the action's arguments does not satisfy this predicate."
    ]
  },
  {
    "name": "USES_REASONING_AS_INPUT",
    "definition": "The action takes an identifiable value, command fragment, or data payload supplied by the reasoning node as an operational input.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action receiving the input."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The prior reasoning node supplying the concrete value, command fragment, or data payload."
      }
    ],
    "assertion_conditions": [
      "The reasoning content contains a concrete value, command option, file content, or configuration fragment.",
      "An argument or payload of the action can be traced to that reasoning content."
    ],
    "exclusion_conditions": [
      "Reasoning used only to choose which action to perform, without supplying the action's input value, does not satisfy this predicate.",
      "A plan that describes the same operation but does not supply the action's concrete argument value is not input use."
    ]
  },
  {
    "name": "USES_REASONING_AS_CRITERION",
    "definition": "The checking action uses a criterion stated in the reasoning node to judge whether an observed result is acceptable.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The checking action that performs the verification."
      },
      {
        "name": "criterion",
        "type": "reasoning",
        "description": "The reasoning node stating the expected result, threshold, or acceptance condition."
      }
    ],
    "assertion_conditions": [
      "The criterion reasoning node states an expected result, threshold, or acceptance condition for a check.",
      "The action performs that check, and the check's arguments or subsequent interpretation are aligned with the stated criterion."
    ],
    "exclusion_conditions": [
      "Reasoning that merely plans to perform a check without stating an expected result or acceptance condition does not satisfy this predicate.",
      "The actual observation is evidence for the check result, not the criterion itself."
    ]
  },
  {
    "name": "GUIDES_ACTION_CHOICE",
    "definition": "The observation supplies the explicit basis for choosing the following action, rather than merely providing a value consumed by that action.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The prior observation whose reported result or failure provides the decision basis."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The following action chosen in light of that observation."
      }
    ],
    "assertion_conditions": [
      "The action follows the observation and responds to a specific reported result, error, or unexpected absence of output in it.",
      "The action's choice of operation or method is explainable by that observation, such as a diagnostic result prompting a different checking or repair method."
    ],
    "exclusion_conditions": [
      "Copying a value from an observation into an action argument is input use, not choice guidance.",
      "Temporal adjacency or a shared topic without evidence that the observation supplied the decision basis does not satisfy this predicate."
    ]
  },
  {
    "name": "DIAGNOSES_FAILURE",
    "definition": "The diagnosis reasoning node explains the cause of the failure reported by the observation.",
    "parameters": [
      {
        "name": "diagnosis",
        "type": "reasoning",
        "description": "The reasoning node that explains the failure's cause."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The prior observation reporting the error or failed result."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the diagnosis and reports an explicit error, fatal condition, nonzero failure, or missing expected result.",
      "The diagnosis identifies a cause for that failure and refers to observable evidence from the failure or related execution, rather than merely restating the error."
    ],
    "exclusion_conditions": [
      "A reasoning node that only proposes a repair without explaining why the failure occurred does not satisfy this predicate.",
      "An unrelated reasoning node following a failure, or a conclusion about a different operation, does not satisfy this predicate."
    ]
  },
  {
    "name": "ATTEMPTS_REPAIR",
    "definition": "The action is performed to remedy the specific failure reported by the preceding observation, by changing the command, environment, permissions, or procedure that failed.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action performed to address the failure."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The prior observation reporting the failure to be remedied."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the action and reports an error, fatal condition, or failure to produce the expected result.",
      "The action targets the same operation or component and differs from the failed attempt in a way that addresses the reported cause."
    ],
    "exclusion_conditions": [
      "Repeating the identical failed operation without a change is not a repair attempt.",
      "An action that is merely the next planned verification step or that addresses a different component is not a repair attempt.",
      "The repair action's success is not required for this predicate; success needs separate confirmation."
    ]
  },
  {
    "name": "CONFIRMS_REPAIR",
    "definition": "The check observation reports successful completion of the same operation that the repair action attempted after the failure observation.",
    "parameters": [
      {
        "name": "repair",
        "type": "action",
        "description": "The action that attempted to remedy the failure."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The prior observation reporting the failure."
      },
      {
        "name": "check",
        "type": "observation",
        "description": "The later observation reporting the outcome of the repair attempt."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the repair action, and the check observation follows the repair action.",
      "The check observation reports a successful result or absence of the prior error for the same operation or component that the repair action targeted.",
      "The repair action differs from the failed attempt and is directed at the failure's cause."
    ],
    "exclusion_conditions": [
      "A successful observation for a different operation, or one that still contains unresolved fatal errors, does not confirm the repair.",
      "A check made before the repair, or a later unrelated verification, does not satisfy this predicate."
    ]
  },
  {
    "name": "DERIVES_CONCLUSION",
    "definition": "The conclusion reasoning node states a conclusion drawn from evidence in the listed observations.",
    "parameters": [
      {
        "name": "inputs",
        "type": "observation[]",
        "description": "The prior observations supplying the evidential basis for the conclusion."
      },
      {
        "name": "conclusion",
        "type": "reasoning",
        "description": "The reasoning node stating the inferred result, cause, or state."
      }
    ],
    "assertion_conditions": [
      "Each input observation precedes the conclusion and contains evidence referenced, summarized, or used by it.",
      "The conclusion states an inferred result, cause, or state that goes beyond copying a single observation."
    ],
    "exclusion_conditions": [
      "A plan for future action, a bare restatement of one observation, or a conclusion with no traceable evidential input does not satisfy this predicate.",
      "Observations that merely share a topic with the conclusion without supplying its evidential basis do not satisfy this predicate."
    ]
  },
  {
    "name": "CLEANS_UP_TEST_ARTIFACTS",
    "definition": "The action removes or resets artifacts created solely for verification so that the environment returns to its pre-test state, as called for by the plan.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action that removes or resets test artifacts."
      },
      {
        "name": "plan",
        "type": "reasoning",
        "description": "The reasoning node stating the intent to clean up or restore the pre-test state."
      }
    ],
    "assertion_conditions": [
      "The plan node states an intent to clean up or restore the pre-test state after verification.",
      "The action deletes, resets, or empties test-specific files, branches, keys, clones, or served content while leaving production configuration intact."
    ],
    "exclusion_conditions": [
      "A general cleanup unrelated to verification artifacts, or deletion of user data, does not satisfy this predicate.",
      "A repair action that fixes a failed operation but does not remove test artifacts is not a cleanup predicate instance."
    ]
  }
]

Existing registry:
[
  {
    "name": "USES_OBSERVATION_AS_INPUT",
    "definition": "The action takes an identifiable value or data payload supplied by the specified prior observation and uses it as an operational input to the action's own arguments or payload.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The tool invocation whose argument or payload receives the data."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The prior recorded tool result that supplies the value or data payload used by the action."
      }
    ],
    "assertion_conditions": [
      "The observation is recorded before the receiving action.",
      "The action's argument or payload can be traced to content of the observation, such as file text reproduced in a write operation or a file name/path used by a later command.",
      "The traceable item is an operational input of the action, not merely a topic shared with it."
    ],
    "exclusion_conditions": [
      "An observation consulted only to decide which action to perform, without contributing a value or payload to its arguments, does not satisfy this predicate.",
      "Temporal adjacency, event membership, or a shared subject without an observable input link does not satisfy this predicate."
    ]
  },
  {
    "name": "USES_REASONING_AS_INPUT",
    "definition": "The action performs an operation using concrete content, such as exact text or a command, that the specified prior reasoning node states, so that the reasoning node supplies the material the action commits.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The tool invocation that enacts the content declared in the reasoning node."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The prior agent text that states the concrete content to be used, such as an exact file body or command."
      }
    ],
    "assertion_conditions": [
      "The reasoning node is recorded before the action.",
      "The reasoning text states concrete content to be used, not only a general intention, goal, or plan step.",
      "The action's argument or payload matches that stated content closely enough that the reasoning node is its evident source."
    ],
    "exclusion_conditions": [
      "Reasoning that only expresses an intention or plan step without specifying the content does not satisfy this predicate.",
      "Reasoning used to judge or evaluate a result, rather than to supply content, does not satisfy this predicate."
    ]
  },
  {
    "name": "GUIDES_ACTION_CHOICE",
    "definition": "The observation reports a diagnostic or probe outcome, such as an error, failure message, or environment/availability result, that is the stated basis for selecting the particular subsequent action or command rather than an alternative.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The recorded diagnostic or probe result that supplies the decision basis."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The later tool invocation whose selection is grounded in that diagnostic result."
      }
    ],
    "assertion_conditions": [
      "The observation precedes the guided action.",
      "Recorded text links the observation's finding to the choice, such as an error being followed by a corrected command or a reported environment result being cited as grounds for proceeding.",
      "The later action differs from a previous attempt in a way responsive to the observation."
    ],
    "exclusion_conditions": [
      "An observation that merely provides a data value consumed as an argument does not satisfy this predicate; that is input supply.",
      "Returning an error without any responsive change in the following action does not satisfy this predicate.",
      "Calls issued in the same event as the observation cannot be guided by it."
    ]
  },
  {
    "name": "ATTEMPTS_REPAIR",
    "definition": "The action is performed with the intent of removing a specific defect that is reported or visible in the specified failure observation, by altering the artifact or the command that exhibited the defect.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The tool invocation intended to remedy the defect."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The recorded result exhibiting the defect, such as missing proof steps, an error message, or a failed check."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the repair action.",
      "The defect is identifiable in the failure observation's content, such as placeholder proof holes or an error naming a wrong module or file argument.",
      "The action's content or arguments are changed to address exactly that defect rather than repeating the prior operation unchanged."
    ],
    "exclusion_conditions": [
      "Re-running an identical operation without addressing the reported defect does not satisfy this predicate.",
      "An action unrelated to the observed defect does not satisfy this predicate.",
      "The predicate does not assert that the repair succeeded; success requires a separate confirming result."
    ]
  },
  {
    "name": "CONFIRMS_REPAIR",
    "definition": "The check observation reports a result obtained after the repair action on the same subject, and that result shows the defect identified in the failure observation is no longer present.",
    "parameters": [
      {
        "name": "repair",
        "type": "action",
        "description": "The remedial action taken against the defect."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The earlier result that exhibited the defect being repaired."
      },
      {
        "name": "check",
        "type": "observation",
        "description": "The later result that assesses whether the defect persists."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the repair action, and the check observation follows it.",
      "The check concerns the same subject or version as the failure, such as the same file, command target, or theorem.",
      "The check reports a success signal for that subject, such as the target artifact being produced cleanly or the compiled theorem being printed without error, rather than another error."
    ],
    "exclusion_conditions": [
      "A check that reports a new or persisting error does not satisfy this predicate.",
      "A check on an unrelated subject or an earlier version does not satisfy this predicate.",
      "The repair action alone, without a following successful check result, does not satisfy this predicate."
    ]
  },
  {
    "name": "DERIVES_CONCLUSION",
    "definition": "The reasoning node states a verdict or outcome whose substantive basis is the findings reported in the specified observations, which the reasoning text cites.",
    "parameters": [
      {
        "name": "inputs",
        "type": "observation[]",
        "description": "The prior recorded results whose findings support the conclusion."
      },
      {
        "name": "conclusion",
        "type": "reasoning",
        "description": "The agent text stating the resulting verdict or outcome."
      }
    ],
    "assertion_conditions": [
      "Every cited observation precedes the conclusion text.",
      "The conclusion text references the specific findings of those observations, such as successful artifact production or successful theorem printing, as the grounds for its verdict.",
      "The observations are substantive evidence for the verdict, not incidental context."
    ],
    "exclusion_conditions": [
      "Reasoning that proposes forthcoming steps rather than asserting an outcome does not satisfy this predicate.",
      "A verdict not grounded in the cited observation content, or grounded only in unrecorded expectations, does not satisfy this predicate.",
      "An observation that merely supplied an argument value does not by itself satisfy this predicate."
    ]
  },
  {
    "name": "DIAGNOSES_OBSERVED_DEFECT",
    "definition": "The reasoning node inspects the content of the specified observation and identifies a specific defect or gap in it, explaining what is missing or wrong as a precondition for fixing it.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that states the diagnosis of the defect."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The recorded result whose content contains the defect being diagnosed."
      }
    ],
    "assertion_conditions": [
      "The observation precedes the diagnosing reasoning text.",
      "The reasoning text names the specific defective or incomplete element present in the observation content, such as placeholder holes that must be filled or an unresolved subgoal, and indicates what is required.",
      "The diagnosis refers to the observation's own content rather than to an assumed or future state."
    ],
    "exclusion_conditions": [
      "Reasoning that merely restates or summarizes the observation content without identifying a defect does not satisfy this predicate.",
      "Reasoning that reports a successful outcome, or that diagnoses something not visible in that observation, does not satisfy this predicate."
    ]
  },
  {
    "name": "IS_PLAN",
    "definition": "The reasoning text states an intended ordered course of forthcoming steps, specifying what will be done next and in what order before results exist.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text containing the prospective step sequence."
      }
    ],
    "assertion_conditions": [
      "The text is future-directed and enumerates or sequences intended actions or subgoals, such as inspecting a file, then completing a proof, then compiling.",
      "The stated steps are presented as the approach to be carried out, not as completed work."
    ],
    "exclusion_conditions": [
      "Past-tense descriptions of what was already done, or final summaries of results, do not satisfy this predicate.",
      "A bare statement of the overall task without an intended sequence does not satisfy this predicate."
    ]
  },
  {
    "name": "EXECUTES_PLANNED_STEP",
    "definition": "The action performs or attempts the concrete operational step that the specified earlier reasoning text presents as an intended course of action, matching the step's described operation and target rather than merely sharing its topic.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The recorded tool invocation that performs or attempts the planned step."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The earlier agent-authored reasoning text that states the intended operational step."
      }
    ],
    "assertion_conditions": [
      "The reasoning node is recorded before the action and is planning or step-describing text, not the action's own observation and not a report of completed work.",
      "The reasoning text describes the step concretely enough to identify its operation and target, such as updating package lists, installing named packages, creating an account with a stated shell, writing a file at a stated path, or validating and starting services.",
      "The action's tool name and arguments correspond to that described operation and target; a plan may contain several steps and this action carries out one of them."
    ],
    "exclusion_conditions": [
      "An action taken for reasons the reasoning never states, or one addressing a different part of the plan, does not satisfy this predicate.",
      "Topic overlap or event co-occurrence without correspondence between the described step and the action's operation and target does not satisfy this predicate.",
      "A planned step that no recorded action carries out establishes no instance of this predicate."
    ]
  },
  {
    "name": "PROVISIONS_OBSERVED_MISSING_COMPONENT",
    "definition": "The action attempts to install, create, or otherwise provision one or more concrete components that the specified earlier observation reported as absent from the environment, so that the observation identifies the provisioning target.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The tool invocation that attempts to install, create, or provision the missing components."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The earlier recorded tool result whose content reports the absence of those components."
      }
    ],
    "assertion_conditions": [
      "The observation's content reports the absence of the component or components, for example a lookup finding no executable for the named tools, or a package, account, or service listing that lacks them.",
      "The action is a provisioning operation such as package installation, account creation, or service setup, and its arguments name the same components or the packages that provide them.",
      "The absence-reporting observation precedes the provisioning action; extra dependencies or related packages may be included in the same provisioning action."
    ],
    "exclusion_conditions": [
      "Provisioning a component that no recorded observation reported absent does not satisfy this predicate; the predicate does not rely on inferred absence.",
      "An action that only inspects availability, or that consumes observed content as an input payload instead of provisioning a missing component, does not satisfy this predicate.",
      "Remedying a recorded error or failed operation is an attempted-repair mechanism, not this absence-driven provisioning mechanism.",
      "The predicate does not assert that provisioning succeeded; confirmation of availability would require a separate result."
    ]
  }
]

Return existing/new/uncertain with complete accounting and unchanged candidate definitions.
